let writeQueue = Promise.resolve();

function enqueueWrite(task) {
    const run = writeQueue.then(task);
    writeQueue = run.then(() => {}, () => {});
    return run;
}

export class ORM {
    constructor(columns = []) {
        this.columns = columns
    }

    getRaw(data = {}) {
        let result = [];
        this.columns.forEach((value, index) => {
            //console.log(index, value ,data[value])

            if (value === 'value') {
                const raw = typeof data[value] === 'object' ? JSON.stringify(data[value]) : data[value];
                const chunks = raw.toString().match(/.{1,49000}/g);
                result[index] = chunks[0];
                result.push(...chunks.slice(1));
            } else {
                result[index] = data[value];
            }

        });
        return result;
    }

    getFormated(data = []) {
        let result = {};
        this.columns.forEach((value, index) => {
            result[value] = data[index];
        });
        return result;
    };

}

export class Table {
    constructor(options) {
        this.list = options.list;
        this.sheets = {}
        this.spreadsheetId = options.spreadsheetId || spreadsheetId;
        this.api = window.GoogleSheetDB || new GoogleSheetDB();
        this.spreadsheets = gapi.client.sheets.spreadsheets;
        this.columns = [];
        try {
            this.columns = JSON.parse(sessionStorage.getItem(options.spreadsheetId + '/' + options.list + '/columns')) || {};
        } catch (e) {

        }
        this.codes = {};
    }

    async exist(){
        return await this.getSheetIdByName(this.list) || false;
    }

    async getSheetIdByName(sheetName) {
        if (this.sheets[sheetName]) return this.sheets[sheetName];
        const response = await this.spreadsheets.get({
            spreadsheetId: this.spreadsheetId,
        });

        const sheet = response.result.sheets.find(
            (s) => s.properties.title === sheetName
        );
        const sheetId = sheet ? sheet.properties.sheetId : null;
        this.sheets[sheetName] = sheetId
        return sheetId;
    }

    async addRawValues(values = []) {
        await enqueueWrite(async () => {
            try {
                await this.spreadsheets.values.append({
                    spreadsheetId: this.spreadsheetId,
                    range: this.list + '!A1:Z1',
                    valueInputOption: "RAW",
                    insertDataOption: "INSERT_ROWS",
                    resource: {
                        majorDimension: "ROWS",
                        values: values,
                        //values: [["Engine", "$100", "1", "3/20/2016"]],
                    }
                });
                //console.log(res);
            } catch (e) {
                console.error(e)
            }
        });
    }

    async addRow(values = {}) {

        if (!this.columns[this.list]) {
            let columnsRaw = sessionStorage.getItem(this.spreadsheetId + '/' + this.list + '/columns');
            if (columnsRaw) {
                this.columns[this.list] = JSON.parse(columnsRaw);
            } else {
                await this.getAll();
            }

        }

        let table = new ORM(this.columns[this.list]);
        let rawValue = table.getRaw(values);
        await this.addRawValues([rawValue]);
        await this.clearListCache();

    }

    async clearListCache() {
        const webStorage = new WebStorage();
        const storageKey = this.list + this.spreadsheetId;
        await webStorage.removeItem(storageKey);
        await webStorage.removeItem(storageKey + '_ttl');
    }

    async addColumns(values = []) {
        await enqueueWrite(async () => {
            try {
                await this.spreadsheets.values.append({
                    spreadsheetId: this.spreadsheetId,
                    range: this.list + '!A1:Z1',
                    valueInputOption: "RAW",
                    insertDataOption: "INSERT_ROWS",
                    resource: {
                        majorDimension: "ROWS",
                        values: [values],
                        //values: [["Engine", "$100", "1", "3/20/2016"]],
                    }
                });
            } catch (e) {
                console.error(e)
            }
        });
    }

    async deleteRow(rowIndex) {
        const sheetId = await this.getSheetIdByName(this.list);

        if (sheetId === null) {
            throw new Error("Лист 'API' не найден");
        }

        await enqueueWrite(async () => {
            await this.spreadsheets.batchUpdate({
                spreadsheetId: this.spreadsheetId,
                resource: {
                    requests: [
                        {
                            deleteDimension: {
                                range: {
                                    sheetId: sheetId,
                                    dimension: "ROWS",
                                    startIndex: rowIndex - 1,
                                    endIndex: rowIndex
                                }
                            }
                        }
                    ]
                }
            });
        });
        await this.clearListCache();
    }

    async updateRow(row, values = {}) {
        //console.log('updateRow', row, values);
        if (!this.columns[this.list]) {
            await this.getColumns(this.list);
        }
        let table = new ORM(this.columns[this.list]);
        let rawValue = table.getRaw(values);

        //console.debug('values.update',new Error().stack);
        await enqueueWrite(async () => {
            try {
                await gapi.client.sheets.spreadsheets.values.update({
                    spreadsheetId: this.spreadsheetId,
                    range: this.list + '!A' + row,
                    valueInputOption: 'RAW',
                    resource: {
                        values: [rawValue]
                    }
                });
            } catch (err) {
                console.error('Value update failed:', err);
            }
        });
        await this.clearListCache();
    }

    async getLists() {
        let response = await this.spreadsheets.get({
            spreadsheetId: this.spreadsheetId,
            fields: 'sheets.properties.title'
        });
        return response.result.sheets;
    }

    async createList(columns = ['code', 'value']) {
        let title = this.list;
        // Сначала получаем информацию о таблице
        await this.spreadsheets.get({
            spreadsheetId: this.spreadsheetId,
            fields: 'sheets.properties.title'
        }).then((response) => {
            const sheets = response.result.sheets;
            const sheetExists = sheets.some(sheet => sheet.properties.title === title);

            if (sheetExists) {
                console.debug(`Лист с названием "${title}" уже существует.`);
                return;
            }

            // Если листа нет, создаем его
            this.spreadsheets.batchUpdate({
                spreadsheetId: this.spreadsheetId,
                requests: [
                    {
                        addSheet: {
                            properties: {
                                title: title
                            }
                        }
                    }
                ]
            }).then((response) => {
                console.log('Лист добавлен:', response.result.replies[0].addSheet.properties.sheetId);
                this.addColumns(columns);
            }).catch((error) => {
                console.error('Ошибка при добавлении листа:', error);
            });
        }).catch((error) => {
            console.error('Ошибка при получении информации о таблице:', error);
        });
    }

    createSpreadSheet(title, callback = null) {
        try {
            this.spreadsheets.create({
                properties: {
                    title: title,
                },
            }).then((response) => {
                if (callback) callback(response);
                console.log('Spreadsheet ID: ' + response.result.spreadsheetId);
            });
        } catch (err) {
            console.error(err.message)
        }
    }

    async clearList() {
        await enqueueWrite(async () => {
            await this.spreadsheets.values.clear({
                spreadsheetId: this.spreadsheetId,
                range: this.list + '!A2:Z1000',
            });
        });
    }

    async getRow(row) {
        let range = this.list + '!' + 'A' + row + ':Z' + row;
        let spreadsheetId = this.spreadsheetId;
        return await this.api.fetchSheetValues({range, spreadsheetId});
    }

    async getAll(options = {}) {
        let {caching=10, formated, range, spreadsheetId, format='array'} = options;
        range = range || this.list;
        spreadsheetId = spreadsheetId || this.spreadsheetId;
        let response = await this.api.fetchSheetValues({range, spreadsheetId, caching});
        if (response){
            this.columns[this.list] = response[0];
            sessionStorage.setItem(spreadsheetId + '/' + this.list + '/columns', JSON.stringify(response[0]));
            this.setCodes(response);
            if (formated) {
                if (format === 'array'){
                    return this.formatData(response);
                } else {
                    let columns = this.columns[this.list] || this.columns;
                    const orm = new ORM(columns);
                    return response.map(e => orm.getFormated(e));
                }
            }
        }

        return response;
    }



    async getColumns(list) {
        if (!this.columns[list]) {
            const range = (list ? list + '!' : '') + 'A1:Z1';
            let spreadsheetId = this.spreadsheetId;
            const values = await this.api.fetchSheetValues({range, spreadsheetId});
            if (values.length > 0) {
                this.columns[list] = values[0];
            }
        }
    }

    setCodes(response) {
        response.forEach((e, i) => {
            this.codes[e[0]] = i
        });
        let storageKey = this.spreadsheetId + '/' + this.list + '/codes';

        sessionStorage.setItem(storageKey, JSON.stringify(this.codes));
    }

    formatData(response) {
        let result = {};

        response.forEach((e) => {
            if ('{['.includes(e[1][0])) {
                result[e[0]] = JSON.parse(e.slice(1).join(''))
            } else {
                result[e[0]] = e[1]
            }
        });
        return result;
    }

    async updateRowByCode(code, values = {}) {
        //console.log('updateRowByCode', code, values);
        let storageKey = this.spreadsheetId + '/' + this.list + '/codes';
        let stored_codes = sessionStorage.getItem(storageKey);

        if (!Object.keys(this.codes).length) {
            if (stored_codes) {
                this.codes = JSON.parse(stored_codes);
            } else {
                await this.getAll()
            }
        }
        if (!values.code){
            values.code = code;
        }
        let id = this.codes[code] + 1;

        if (id) {
            await this.updateRow(id, values);
            return true;
        }

        this.codes = {};
        await this.getAll();
        id = this.codes[code] + 1;

        if (id) {
            await this.updateRow(id, values);
            return true;
        }

        await this.addRow(values);
        return false;
    }

    async addRows(values = []) {
        if (!this.columns[this.list]) {
            let columnsRaw = sessionStorage.getItem(this.spreadsheetId + '/' + this.list + '/columns');
            if (columnsRaw) {
                this.columns[this.list] = JSON.parse(columnsRaw);
            } else {
                await this.getAll();
            }

        }

        let table = new ORM(this.columns[this.list]);
        let rawValues = [];
        values.forEach((e)=>{
            rawValues.push(table.getRaw(e))
        });

        await enqueueWrite(async () => {
            try {
                await this.spreadsheets.values.append({
                    spreadsheetId: this.spreadsheetId,
                    range: this.list + '!A1:Z1',
                    valueInputOption: "RAW",
                    insertDataOption: "INSERT_ROWS",
                    resource: {
                        majorDimension: "ROWS",
                        values: rawValues,
                        //values: [["Engine", "$100", "1", "3/20/2016"]],
                    }
                });
            } catch (e) {
                console.error(e)
            }
        });
        await this.clearListCache();
    }
}

export class Drive {
     prom(gapiCall, argObj) {
        return new Promise((resolve, reject) => {
            gapiCall(argObj).then(resp => {
                if (resp && (resp.status < 200 || resp.status > 299)) {
                    console.log('GAPI call returned bad status', resp)
                    reject(resp)
                } else {
                    resolve(resp)
                }
            }, err => {
                console.log('GAPI call failed', err)
                reject(err)
            })
        })
    }

    // ===== Helpers for regular Drive (not appDataFolder) =====
    async findFolderByName(name, parentId = 'root') {
        const queryParts = [
            `mimeType = 'application/vnd.google-apps.folder'`,
            `name = '${name.replace(/'/g, "\\'")}'`,
            `trashed = false`,
        ];
        if (parentId) {
            queryParts.push(`'${parentId}' in parents`);
        }
        const q = queryParts.join(' and ');
        const resp = await this.prom(gapi.client.drive.files.list, {
            spaces: 'drive',
            fields: 'files(id, name)',
            pageSize: 10,
            q,
        });
        return (resp.result.files && resp.result.files[0]) ? resp.result.files[0] : null;
    }

    async createFolder(name, parentId = 'root') {
        const resp = await this.prom(gapi.client.drive.files.create, {
            resource: {
                name,
                mimeType: 'application/vnd.google-apps.folder',
                parents: parentId ? [parentId] : undefined,
            },
            fields: 'id, name'
        });
        return resp.result;
    }

    async ensureFolderPath(pathSegments = []) {
        let currentParent = 'root';
        let lastFolder = null;
        for (const segment of pathSegments) {
            let folder = await this.findFolderByName(segment, currentParent);
            if (!folder) {
                folder = await this.createFolder(segment, currentParent);
            }
            currentParent = folder.id;
            lastFolder = folder;
        }
        return lastFolder; // {id, name}
    }

    async moveFileToFolder(fileId, folderId) {
        // Get current parents
        const file = await this.prom(gapi.client.drive.files.get, {
            fileId,
            fields: 'parents'
        });
        const previousParents = (file.result.parents || []).join(',');
        const resp = await this.prom(gapi.client.drive.files.update, {
            fileId,
            addParents: folderId,
            removeParents: previousParents,
            fields: 'id, parents'
        });
        return resp.result;
    }

    /**
     * Создает бэкап Google таблицы с датой и временем в названии
     * @param {string} spreadsheetId - ID таблицы для бэкапа
     * @returns {Promise<string>} - ID созданного бэкапа
     */
    async createSpreadsheetBackup(spreadsheetId) {
        try {
            // Получаем информацию об оригинальной таблице
            const originalSpreadsheet = await this.prom(gapi.client.sheets.spreadsheets.get, {
                spreadsheetId: spreadsheetId,
                fields: 'properties.title,sheets.properties.title'
            });

            const originalTitle = originalSpreadsheet.result.properties.title;
            const sheets = originalSpreadsheet.result.sheets;
            
            // Создаем название бэкапа с датой и временем
            const now = new Date();
            const dateStr = now.toISOString().slice(0, 19).replace(/:/g, '-');
            const backupTitle = `${originalTitle}_BACKUP_${dateStr}`;
            
            console.log(`Создание бэкапа: ${backupTitle}`);
            
            // Создаем новую таблицу для бэкапа
            const newSpreadsheet = await this.prom(gapi.client.sheets.spreadsheets.create, {
                properties: {
                    title: backupTitle
                }
            });
            
            const backupSpreadsheetId = newSpreadsheet.result.spreadsheetId;
            console.log(`Бэкап создан с ID: ${backupSpreadsheetId}`);

            // Перемещаем файл в папку dndapp/backups
            const backupsFolder = await this.ensureFolderPath(['dndapp', 'backups']);
            if (backupsFolder && backupsFolder.id) {
                await this.moveFileToFolder(backupSpreadsheetId, backupsFolder.id);
                console.log('Бэкап перемещен в папку dndapp/backups');
            } else {
                console.warn('Не удалось обеспечить папку dndapp/backups');
            }
            
            // Получаем текущие листы в бэкапе (по умолчанию есть один)
            const backupMeta = await this.prom(gapi.client.sheets.spreadsheets.get, {
                spreadsheetId: backupSpreadsheetId,
                fields: 'sheets.properties.sheetId,sheets.properties.title'
            });
            const backupSheetMap = {};
            (backupMeta.result.sheets || []).forEach(s => {
                backupSheetMap[s.properties.title] = s.properties.sheetId;
            });

            // Копируем все листы из оригинальной таблицы
            for (const sheet of sheets) {
                const sheetTitle = sheet.properties.title;
                
                // Получаем данные листа
                const sheetData = await this.prom(gapi.client.sheets.spreadsheets.values.get, {
                    spreadsheetId: spreadsheetId,
                    range: sheetTitle
                });
                
                if (sheetData.result.values && sheetData.result.values.length > 0) {
                    // Убеждаемся, что лист существует в бэкапе
                    if (!backupSheetMap[sheetTitle]) {
                        const addResp = await this.prom(gapi.client.sheets.spreadsheets.batchUpdate, {
                            spreadsheetId: backupSpreadsheetId,
                            resource: {
                                requests: [
                                    {
                                        addSheet: {
                                            properties: {
                                                title: sheetTitle
                                            }
                                        }
                                    }
                                ]
                            }
                        });
                        const newSheetId = addResp.result.replies[0].addSheet.properties.sheetId;
                        backupSheetMap[sheetTitle] = newSheetId;
                    }
                    
                    // Заполняем лист данными
                    await this.prom(gapi.client.sheets.spreadsheets.values.update, {
                        spreadsheetId: backupSpreadsheetId,
                        range: `${sheetTitle}!A1`,
                        valueInputOption: 'RAW',
                        resource: {
                            values: sheetData.result.values
                        }
                    });
                    
                    console.log(`Лист "${sheetTitle}" скопирован`);
                }
            }
            
            console.log(`Бэкап "${backupTitle}" успешно создан`);
            return backupSpreadsheetId;
            
        } catch (error) {
            console.error('Ошибка при создании бэкапа:', error);
            throw error;
        }
    }
    async createEmptyFile(name, mimeType) {
        const resp = await this.prom(gapi.client.drive.files.create, {
            resource: {
                name: name,
                // для создания папки используйте
                // mimeType = 'application/vnd.google-apps.folder'
                mimeType: mimeType || 'text/plain',
                // вместо 'appDataFolder' можно использовать ID папки
                parents: ['appDataFolder']
            },
            fields: 'id'
        })
        // функция возвращает строку — идентификатор нового файла
        return resp.result.id
    }
    async upload(fileId, content) {
        // функция принимает либо строку, либо объект, который можно сериализовать в JSON
        return this.prom(gapi.client.request, {
            path: `/upload/drive/v3/files/${fileId}`,
            method: 'PATCH',
            params: {uploadType: 'media'},
            body: typeof content === 'string' ? content : JSON.stringify(content)
        })
    }

    async download(fileId) {
        const resp = await this.prom(gapi.client.drive.files.get, {
            fileId: fileId,
            alt: 'media'
        })
        // resp.body хранит ответ в виде строки
        // resp.result — это попытка интерпретировать resp.body как JSON.
        // Если она провалилась, значение resp.result будет false
        // Т.о. функция возвращает либо объект, либо строку
        return resp.result || resp.body
    }
    async find(query) {
        let ret = []
        let token
        do {
            const resp = await this.prom(gapi.client.drive.files.list, {
                // вместо 'appDataFolder' можно использовать ID папки
                spaces: 'appDataFolder',
                fields: 'files(id, name), nextPageToken',
                pageSize: 100,
                pageToken: token,
                orderBy: 'createdTime',
                q: query
            })
            ret = ret.concat(resp.result.files)
            token = resp.result.nextPageToken
        } while (token)
        // результат: массив объектов вида [{id: '...', name: '...'}],
        // отсортированных по времени создания
        return ret
    }

    async deleteFile(fileId) {
        try {
            await this.prom(gapi.client.drive.files.delete, {
                fileId: fileId
            })
            return true
        } catch (err) {
            if (err.status === 404) {
                return false
            }
            throw err
        }
    }
}

export class GoogleSheetDB {
    constructor(options = {}) {
        this.DISCOVERY_DOC = 'https://sheets.googleapis.com/$discovery/rest?version=v4';

        this.apiKey = API_KEY;
        this.tokenClient = {};
        this.gapiInited = false;
        this.gisInited = false;
        this.authorize_button = document.getElementById('authorize_button')

        this.headers = [];
        this.columns = {};

        if (this.expired()){
            localStorage.setItem('gapi_token', '');
        }
        this.storedToken = localStorage.getItem('gapi_token');
        this.callback = options.callback;
        loadScriptOnce({
            src: 'https://apis.google.com/js/api.js',
            onload: this.gapiLoaded.bind(this),
        });

        loadScriptOnce({
            src: 'https://accounts.google.com/gsi/client',
            onload: this.gisLoaded.bind(this),
        });

        let timer = setInterval(async () => {
            if (document.getElementById('signout_button')){
                document.getElementById('signout_button').textContent =
                    localStorage.getItem('gapi_token_expires') - this.getTime();
            }
            let settingButton = document.querySelector('[onclick="showTab(\'settings-tab\')"]');
            if (this.expired()) {
                console.log('нужно авторизоваться');
                document.body.dispatchEvent(new Event('doAuth'));
                clearInterval(timer);
                if (settingButton) settingButton.style.backgroundColor = 'red'
            } else {
                if (settingButton) settingButton.style.backgroundColor = ''
            }
        })
        window.GoogleSheetDB = this;
    }

    async waitGoogle(timeout = 10000) {
        //console.trace('ждем гугла');
        const startTime = Date.now();
        while (!(this.gapiInited && this.gisInited)) {
            if (Date.now() - startTime > timeout) {
                throw new Error('Инициализация Google API не завершена в течение отведенного времени.'
                    + this.gapiInited + ' ' + this.gisInited);
            }
            await new Promise(resolve => setTimeout(resolve, 100));
        }
    }

    async waitRead(timeout = 10000) {
        const startTime = Date.now();
        while (!this.gapiInited) {
            if (Date.now() - startTime > timeout) {
                throw new Error('Инициализация Google API не завершена в течение отведенного времени.'
                    + this.gapiInited + ' ' + this.gisInited);
            }
            await new Promise(resolve => setTimeout(resolve, 100));
        }
    }


    async waitWrite(timeout = 10000) {
        const startTime = Date.now();
        while (!this.gisInited) {
            if (Date.now() - startTime > timeout) {
                throw new Error('Инициализация Google API не завершена в течение отведенного времени.'
                    + this.gapiInited + ' ' + this.gisInited);
            }
            await new Promise(resolve => setTimeout(resolve, 100));
        }
    }

    expired() {
        return localStorage.getItem('gapi_token_expires') - this.getTime() < 10
    }

    getTime() {
        return Math.floor(Date.now() / 1000)
    }

    async gapiLoaded() {
        gapi.load('client', this.initializeGapiClient.bind(this));
    }


    maybeEnableButtons() {
        if (this.gapiInited && this.gisInited) {
            if (this.authorize_button){
                this.authorize_button.style.visibility = 'visible';
            }
        }
    }

    async initializeGapiClient() {
        await gapi.client.init({
            apiKey: this.apiKey,
            discoveryDocs: [DISCOVERY_DOC_CALENDAR, DISCOVERY_DOC_SHEETS, DISCOVERY_DOC_DRIVE],
        });

        if (this.storedToken) {
            try {
                const parsedToken = JSON.parse(this.storedToken);
                gapi.client.setToken(parsedToken);
            } catch (e) {
                console.warn('Failed to parse stored token:', e);
            }
        }

        this.gapiInited = true;
        if (this.callback) this.callback();

        this.maybeEnableButtons();
    }

    gisLoaded() {
        this.tokenClient = google.accounts.oauth2.initTokenClient({
            client_id: CLIENT_ID,
            scope: SCOPES,
            discoveryDocs: [DISCOVERY_DOC_CALENDAR, DISCOVERY_DOC_SHEETS,DISCOVERY_DOC_DRIVE],
            callback: () => {
            }, // пустой, определим в handleAuthClick
        });
        this.gisInited = true;
        this.maybeEnableButtons();
        this.eventHandler();
    }

    eventHandler() {
        if (this.authorize_button){
            this.authorize_button.onclick = this.handleAuthClick.bind(this,()=>{
                location.reload();
            });
        }
        if (document.getElementById('signout_button')){
            document.getElementById('signout_button').onclick = this.handleSignoutClick.bind(this);
        }
    }

    handleAuthClick(callback) {
        this.tokenClient.callback = async (resp) => {
            if (resp.error !== undefined) {
                throw (resp);
            }
            document.getElementById('signout_button').style.visibility = 'visible';
            this.authorize_button.innerText = 'Refresh';

            // Сохраняем токен в localStorage
            const token = gapi.client.getToken();
            localStorage.setItem('gapi_token', JSON.stringify(token));
            localStorage.setItem('gapi_token_expires', JSON.stringify(this.getTime() + resp.expires_in));

            callback();
        };

        if (gapi.client.getToken() === null) {
            this.tokenClient.requestAccessToken({prompt: 'consent'});
        } else {
            this.tokenClient.requestAccessToken({prompt: ''});
        }
    }

    handleSignoutClick() {
        const token = gapi.client.getToken();
        if (token !== null) {
            google.accounts.oauth2.revoke(token.access_token);
            gapi.client.setToken('');
            localStorage.removeItem('gapi_token'); // удаляем токен из localStorage
            document.getElementById('content').innerText = '';
            this.authorize_button.innerText = 'Authorize';

        }
    }

    async fetchSheetValues(options) {
        const webStorage = new WebStorage();

        let {range, spreadsheetId, caching} = options;
        let response;
        let data = [];
        let storageKey = range + spreadsheetId;
        let storageTTLKey = range + spreadsheetId + '_ttl';
        let storageData = await webStorage.getItem(storageKey);
        let storageTTL = await webStorage.getItem(storageTTLKey);
        let now = new Date().getTime();

        if (caching && storageData ) {
            if (storageTTL > now){
                //console.info(storageKey + ' кэш еще нормальный')
                return JSON.parse(storageData);
            }
        }
        try {
            response = await gapi.client.sheets.spreadsheets.values.get({
                spreadsheetId,
                range: range,
            });
            //console.debug('values.get', new Error().stack);
        } catch (err) {
            console.error(err);
            return data;
        }
        const result = response.result;
        if (!result || !result.values || result.values.length === 0) {
            console.error('No values found.');
            return data;
        }
        data = result.values;
        await webStorage.setItem(storageKey, JSON.stringify(data));
        await webStorage.setItem(storageTTLKey, new Date().getTime() + parseInt(caching)*1000);
        return data;
    }
}

function loadScriptOnce({src, onload, async = true, defer = true}) {
    // Проверяем, не загружен ли уже скрипт
    const existingScript = Array.from(document.getElementsByTagName('script'))
        .find(script => script.src === src);

    if (existingScript) {
        console.log(`Скрипт уже загружен: ${src}`);
        onload();
        return;
    }

    // Создаём новый <script> элемент
    const script = document.createElement('script');
    script.src = src;
    script.async = async;
    script.defer = defer;
    if (onload && typeof onload === 'function') {
        script.onload = onload;
    }

    // Вставляем скрипт в <head>
    document.head.appendChild(script);
}


